/*
 * A215142  Numbers k such that the difference between the greatest prime
 *          divisor of k and the sum of the other distinct prime divisors
 *          equals 1.
 * https://oeis.org/A215142
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the n‑th integer k such that * the greatest prime divisor
 *            of k minus the sum of the other distinct * prime divisors equals
 *            1. The sequence is generated by testing all * natural numbers in
 *            increasing order
 * Range:     u8 n <= 15, u16 n <= 453, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   factor_u64
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Standard headers */
#include <stdlib.h>
#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>

/* Helper for factorising a 64‑bit integer into distinct primes. */
#include "../utils/factor_u64.h"

/* Static cache of already‑found terms */
static seq_t *cache = NULL;     /* array of terms */
static size_t cache_len = 0;    /* number of terms stored */
static size_t cache_cap = 0;    /* allocated capacity of the array */

/* Next integer to test for membership in the sequence */
static uint64_t next_candidate = 2;

/* Ensure the cache has room for at least 'need' entries. */
static void ensure_cache_capacity(size_t need)
{
    if (need <= cache_cap)
        return;
    size_t new_cap = cache_cap ? cache_cap * 2 : 64;
    if (new_cap < need)
        new_cap = need;
    seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
    if (!tmp) {
        /* In a real implementation we might handle the allocation error
         * more gracefully, but aborting is acceptable for our purposes. */
        abort();
    }
    cache = tmp;
    cache_cap = new_cap;
}

/* Append a found term to the cache. */
static void append_term(seq_t val)
{
    ensure_cache_capacity(cache_len + 1);
    cache[cache_len++] = val;
}

/* Test whether m satisfies the definition of the sequence. */
static bool satisfies(uint64_t m)
{
    /* We need at least two distinct prime divisors. */
    if (m < 6)
        return false;

    /* Factorise m into distinct primes. */
    /* The number of distinct prime factors of a 64‑bit integer is
     * small; an array of 32 is more than enough. */
    uint64_t primes_arr[32];
    uint64_t exps_arr[32];
    size_t cnt = 0;
    factor_u64(m, primes_arr, exps_arr, &cnt);

    if (cnt < 2)
        return false;

    uint64_t largest = primes_arr[cnt - 1];
    uint64_t sum_others = 0;
    for (size_t i = 0; i + 1 < cnt; ++i)
        sum_others += primes_arr[i];

    return (largest - sum_others) == 1;
}

/* The required function. */
seq_t a(idx_t n)
{
    /* The OEIS offset is 1, but we accept a(0) by returning 0. */
    if (n == 0)
        return 0;

    /* Grow the cache until it contains at least n terms. */
    while (cache_len < (size_t)n) {
        if (satisfies(next_candidate))
            append_term((seq_t)next_candidate);
        ++next_candidate;
    }

    return cache[(size_t)n - 1];
}
